(() => {
  const STORAGE_KEY = 'internpilot-prototype-v3';
  const catalog = [
    {id:'sample-1', company:'示例企业 A', title:'AI 产品经理实习生', city:'上海', schedule:'每周 3 天', requirements:[
      {key:'user-research',label:'用户研究与需求分析',quote:'参与用户需求调研，整理产品需求文档',must:true},
      {key:'solution',label:'产品方案表达',quote:'能够输出清晰的需求文档或产品方案',must:true},
      {key:'data',label:'数据分析意识',quote:'关注功能使用数据并参与效果复盘',must:false}]},
    {id:'sample-2', company:'示例企业 B', title:'产品策划实习生', city:'上海', schedule:'每周 3 天', requirements:[
      {key:'user-research',label:'用户研究与需求分析',quote:'协助用户访谈和需求分析',must:true},
      {key:'solution',label:'产品方案表达',quote:'参与产品流程和原型设计',must:false},
      {key:'collaboration',label:'跨团队沟通',quote:'与设计、研发同学协作推进方案',must:false}]},
    {id:'sample-3', company:'示例企业 C', title:'智能产品实习生', city:'上海', schedule:'每周 3 天', requirements:[
      {key:'user-research',label:'用户研究与需求分析',quote:'完成竞品与用户需求研究',must:false},
      {key:'data',label:'数据分析意识',quote:'整理产品数据并提出改进建议',must:true},
      {key:'ai-tools',label:'AI 产品理解',quote:'了解常见 AI 产品能力与使用场景',must:false}]},
    {id:'sample-4', company:'示例企业 D', title:'AI 应用产品实习生', city:'上海', schedule:'每周 4 天', requirements:[
      {key:'user-research',label:'用户研究与需求分析',quote:'参与目标用户研究',must:false},
      {key:'solution',label:'产品方案表达',quote:'参与 AI 应用产品方案设计',must:true},
      {key:'data',label:'数据分析意识',quote:'分析功能使用数据',must:false}]}
  ];
  const pages = [
    ['goal','目标与岗位'],['evidence','经历与对照'],['plans','准备计划'],['today','执行计划'],['review','成果与复盘']
  ];
  const initialState = () => ({
    page:'goal',goal:{title:'',city:'',hours:6,days:''},savedJobIds:[],archivedJobIds:[],shortlistJobIds:[],customJobs:[],jobStatus:{},jobDrafts:{},applicationRecords:[],jobSnapshots:{},materials:[],
    experiences:[],answers:{},evidenceConfirmed:false,plans:[],outcomes:[],feedback:[]
  });
  const $ = (selector,root=document) => root.querySelector(selector);
  const $$ = (selector,root=document) => [...root.querySelectorAll(selector)];
  const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const uid = prefix => `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;
  let state;
  try { state = {...initialState(), ...JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}')}; } catch { state = initialState(); }
  if (!pages.some(([key])=>key===state.page)) state.page='goal';
  const save = () => localStorage.setItem(STORAGE_KEY,JSON.stringify(state));
  const allJobs = () => [...catalog,...state.customJobs];
  const jobById = id => allJobs().find(job=>job.id===id);
  const savedJobs = () => state.savedJobIds.map(jobById).filter(Boolean);
  const archivedJobs = () => state.archivedJobIds.map(jobById).filter(Boolean);
  const statusLabel = status => ({saved:'未投递',applied:'已投递',waiting:'等待反馈',interview:'面试中',closed:'已结束'})[status]||'未投递';
  const latestApplication = id => [...state.applicationRecords].reverse().find(record=>record.jobId===id);
  const experienceById = id => state.experiences.find(x=>x.id===id);
  const hours = value => `${Number(value || 0).toFixed(Number(value || 0)%1?1:0)} 小时`;
  const pageNumber = key => pages.findIndex(([id])=>id===key)+1;
  function toast(message){const node=$('#toast');node.textContent=message;node.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('show'),2900)}
  function requirements(){
    const map=new Map();
    for(const job of savedJobs())for(const item of job.requirements){
      if(!map.has(item.key))map.set(item.key,{key:item.key,label:item.label,count:0,must:0,sources:[]});
      const row=map.get(item.key);row.count++;row.must+=item.must?1:0;row.sources.push({company:job.company,job:job.title,quote:item.quote,must:item.must});
    }
    return [...map.values()].sort((a,b)=>(b.count+b.must*2)-(a.count+a.must*2)||a.label.localeCompare(b.label,'zh-CN'));
  }
  function priority(row){if(row.must&&row.count>=2)return ['高优先级','blue'];if(row.must)return ['明确门槛','amber'];if(row.count>=2)return ['共同要求','blue'];return ['岗位特定',''];}
  function head(step,title,description,action=''){
    return `<div class="flow-strip">${pages.map(([id,label],index)=>`<span class="node ${state.page===id?'current':''}">${index+1} ${label}</span>${index<pages.length-1?'<span class="arrow">→</span>':''}`).join('')}</div><div class="page-head"><div><div class="eyebrow">第 ${step} 步 · InternPilot</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
  }
  function renderNav(){
    $('#side-nav').innerHTML=pages.map(([id,label],index)=>`<button class="nav-button ${state.page===id?'active':''}" data-page="${id}" type="button"><span class="nav-number">${index+1}</span>${label}</button>`).join('');
    $('#top-label').textContent=pages.find(([id])=>id===state.page)?.[1] || '求职准备';
  }
  function render(){renderNav();const content={goal:renderGoal,evidence:renderEvidence,plans:renderPlans,today:renderToday,review:renderReview}[state.page]();$('#main-content').innerHTML=`<div class="page">${content}<div class="prototype-note">这是交互原型：岗位与建议为演示内容；不会连接招聘平台、自动投递或调用真实 AI。你输入的内容只保存在当前浏览器。</div></div>`;}
  function navigate(page){state.page=page;save();render();document.body.classList.remove('nav-open');window.scrollTo({top:0,behavior:'instant'});$('#main-content').focus({preventScroll:true})}
  function renderFolderJob(job){
    const shortlisted=state.shortlistJobIds.includes(job.id), custom=state.customJobs.some(item=>item.id===job.id), record=latestApplication(job.id), draftCount=state.jobDrafts[job.id]?.length||0;
    return `<div class="folder-job"><div class="folder-job-head"><div><strong>${escapeHtml(job.title)}</strong><p>${escapeHtml(job.company)} · ${escapeHtml(job.city||'城市未设置')} · ${job.requirements.length} 项要求</p></div><span class="tag ${shortlisted?'blue':''}">${shortlisted?'优先推进':'候选岗位'}</span></div><div class="folder-job-meta"><span class="tag">${statusLabel(state.jobStatus[job.id])}</span><span>${record?escapeHtml(record.date)+' 更新':state.jobStatus[job.id]&&state.jobStatus[job.id]!=='saved'?'旧状态待补记录':'尚无投递记录'}</span><span>${draftCount} 版沟通草稿</span></div><div class="folder-job-controls"><button class="button small ${shortlisted?'':'primary'}" data-act="shortlist-job" data-id="${escapeHtml(job.id)}">${shortlisted?'取消优先':'优先推进'}</button><button class="button small" data-act="view-job" data-id="${escapeHtml(job.id)}">查看依据</button>${custom?`<button class="button small" data-act="edit-job" data-id="${escapeHtml(job.id)}">编辑岗位</button>`:''}<button class="button small" data-act="draft-job" data-id="${escapeHtml(job.id)}">沟通草稿</button><button class="button small" data-act="application-job" data-id="${escapeHtml(job.id)}">投递记录</button><button class="button ghost small" data-act="archive-job" data-id="${escapeHtml(job.id)}">归档</button></div></div>`;
  }
  function renderArchivedJob(job){return `<div class="job-row"><div><strong>${escapeHtml(job.title)}</strong><p>${escapeHtml(job.company)} · 已归档，暂不参与要求汇总</p></div><div class="row"><button class="button small" data-act="view-job" data-id="${escapeHtml(job.id)}">查看依据</button>${latestApplication(job.id)?`<button class="button small" data-act="application-job" data-id="${escapeHtml(job.id)}">更新状态</button>`:''}<button class="button small" data-act="restore-job" data-id="${escapeHtml(job.id)}">恢复到文件夹</button></div></div>`;}
  function renderGoal(){
    const jobs=savedJobs(), reqs=requirements();
    const catalogCards=catalog.map(job=>`<article class="card job-card"><div><div class="card-header"><div><h3>${escapeHtml(job.title)}</h3><div class="company">${escapeHtml(job.company)} · ${escapeHtml(job.city)} · ${escapeHtml(job.schedule)}</div></div><span class="tag">示例岗位</span></div><div class="requirements">${job.requirements.map(r=>escapeHtml(r.label)).join(' · ')}</div></div><div class="actions"><button class="button small ${state.savedJobIds.includes(job.id)?'':'primary'}" data-act="toggle-job" data-id="${job.id}" type="button">${state.savedJobIds.includes(job.id)?'移出文件夹':'收藏到文件夹'}</button><button class="button ghost small" data-act="view-job" data-id="${job.id}" type="button">查看要求</button></div></article>`).join('');
    const ownCards=state.customJobs.map(job=>`<article class="card job-card"><div><h3>${escapeHtml(job.title)}</h3><div class="company">${escapeHtml(job.company)} · ${escapeHtml(job.city||'未设置城市')}</div><div class="requirements">${job.requirements.map(r=>escapeHtml(r.label)).join(' · ')}</div></div><div class="actions"><button class="button small ${state.savedJobIds.includes(job.id)?'':'primary'}" data-act="toggle-job" data-id="${escapeHtml(job.id)}" type="button">${state.savedJobIds.includes(job.id)?'移出文件夹':'收藏到文件夹'}</button><button class="button ghost small" data-act="view-job" data-id="${escapeHtml(job.id)}" type="button">查看要求</button></div></article>`).join('');
    const savedRows=jobs.map(renderFolderJob).join('');
    const reqRows=reqs.map(row=>{const [label,tone]=priority(row);return `<tr><td><strong>${escapeHtml(row.label)}</strong><details><summary>查看原文依据</summary>${row.sources.map(source=>`<span class="source-line">${escapeHtml(source.company)}：「${escapeHtml(source.quote)}」${source.must?' · 必备':''}</span>`).join('')}</details></td><td>${row.count}/${jobs.length} 条岗位</td><td><span class="tag ${tone}">${label}</span></td></tr>`}).join('');
    const archivedPanel=`<section class="section"><div class="section-head"><div><h2>已归档岗位</h2><p>不再参与当前要求汇总；草稿和投递历史仍会保留，可随时恢复。</p></div><span class="tag">${archivedJobs().length} 条</span></div>${archivedJobs().length?`<div class="card">${archivedJobs().map(renderArchivedJob).join('')}</div>`:'<div class="empty"><strong>暂无归档岗位</strong><p>暂时不推进的岗位可以从目标文件夹归档。</p></div>'}</section>`;
    const applicationPanel=`<section class="section"><div class="section-head"><div><h2>投递与状态历史</h2><p>只记录本人确认的实际操作；更新不会覆盖旧记录。</p></div><span class="tag">${state.applicationRecords.length} 条记录</span></div>${state.applicationRecords.length?`<div class="card">${[...state.applicationRecords].reverse().map(record=>{const job=jobById(record.jobId);return `<div class="job-row"><div><strong>${escapeHtml(job?.title||'原岗位')} · ${statusLabel(record.status)}</strong><p>${escapeHtml(record.date)} · ${escapeHtml(record.note||'无备注')}</p></div><span class="tag green">本人确认</span></div>`}).join('')}</div>`:'<div class="empty"><strong>还没有投递记录</strong><p>优先推进岗位后，在原招聘平台操作，再回到文件夹填写日期和实际状态。</p></div>'}</section>`;
    const jobFlowPanel=`<div class="notice job-flow"><strong>这一步如何推进</strong><div class="job-flow-steps"><span>① 收集 JD 与来源</span><span>② 核对岗位条件</span><span>③ 选入优先推进</span><span>④ 编辑沟通草稿</span><span>⑤ 本人到原平台投递</span><span>⑥ 回来记录和跟进</span></div><p>链接读取失败或未授权时，保留来源并手动粘贴 JD；没有投递成功的确认，不改变申请状态。</p><div class="actions"><button class="button small" data-page="evidence">先整理个人材料</button></div></div>`;
    return head(1,'从目标出发，收集真实岗位','先设定方向，再将多个具体岗位放进同一文件夹。岗位要求的总结始终可以追溯到原文。')+
      (!state.goal.title?'<div class="notice"><strong>第一次使用，从这里开始</strong><p>系统目前没有你的目标和经历。你填写目标后，可以收藏岗位；经历将在下一步由你逐项提供。</p></div>':'')+
      `<div class="grid goal-layout"><section class="card"><div class="card-header"><h2>我的求职目标</h2><span class="tag ${state.goal.title?'green':''}">${state.goal.title?'已设定':'待设定'}</span></div><form id="goal-form"><label class="field"><span>目标岗位或职业方向 *</span><input name="title" required placeholder="如：AI 产品经理实习" value="${escapeHtml(state.goal.title)}"></label><div class="field-row"><label class="field"><span>求职城市</span><input name="city" placeholder="如：上海" value="${escapeHtml(state.goal.city)}"></label><label class="field"><span>每周可用于准备的时间</span><input name="hours" type="number" min="1" max="40" step="0.5" value="${escapeHtml(state.goal.hours)}"></label></div><label class="field"><span>到岗或申请时间偏好</span><input name="days" placeholder="如：每周 3 天、下月开始" value="${escapeHtml(state.goal.days)}"></label><div class="actions"><button class="button primary" type="submit">保存目标</button></div></form></section><section class="card soft"><div class="card-header"><div><h2>目标文件夹</h2><p class="caption">${state.goal.title?escapeHtml(`${state.goal.city||'不限城市'} · ${state.goal.title}`):'设定目标后创建文件夹'}</p></div><button class="button small" data-act="open-custom-job">+ 添加岗位</button></div><div class="row"><span class="tag blue">${jobs.length} 条已收藏岗位</span><span class="tag">${reqs.length} 项汇总要求</span></div><p class="caption">同一文件夹收集多个岗位。收藏不等于投递，状态由你更新。</p><div class="folder-job-list">${savedRows||'<div class="folder-empty">还没有岗位。可以从下方示例中收藏，或手动添加你找到的岗位。</div>'}</div></section></div>`+
      jobFlowPanel+`<section class="section"><div class="section-head"><div><h2>发现与收藏岗位</h2><p>以下均为演示岗位，也可以手动添加你找到的真实岗位。</p></div><label class="field job-filter"><span>筛选演示岗位</span><input data-job-filter type="search" placeholder="岗位、公司或城市"></label></div><div class="grid three">${catalogCards}${ownCards}</div></section>`+
      `<section class="section"><div class="section-head"><div><h2>岗位要求地图</h2><p>出现次数与“必备”标记一起帮助排序；每条判断都可查看原文。</p></div></div>${reqs.length?`<div class="card"><table class="requirements-table"><thead><tr><th>要求与依据</th><th>覆盖岗位</th><th>初步优先级</th></tr></thead><tbody>${reqRows}</tbody></table><div class="actions"><button class="button primary" data-page="evidence">按这些要求核对经历 →</button></div></div>`:'<div class="empty"><strong>等待具体岗位</strong><p>你收藏的岗位将决定下一步需要逐项核对哪些经历。</p></div>'}</section>`+archivedPanel+applicationPanel;
  }
  function statusSelected(id,status){return (state.jobStatus[id]||'saved')===status?'selected':''}
  function renderEvidence(){
    const reqs=requirements();const answered=reqs.filter(row=>answerComplete(row.key)).length;
    const experienceList=state.experiences.length?state.experiences.map(exp=>`<div class="experience-card"><div class="between"><div><strong>${escapeHtml(exp.title)}</strong><div class="muted">${escapeHtml(exp.type)}${exp.period?' · '+escapeHtml(exp.period):''}</div></div><span class="tag ${exp.confirmed?'green':'amber'}">${exp.confirmed?'本人已核对':'待核对'}</span></div><p>${escapeHtml(exp.description)}</p>${exp.link?`<a href="${escapeHtml(safeUrl(exp.link))}" target="_blank" rel="noopener noreferrer" class="caption">查看成果链接 ↗</a>`:''}<div class="actions"><button class="button small" data-act="edit-experience" data-id="${escapeHtml(exp.id)}">编辑</button><button class="button small danger" data-act="remove-experience" data-id="${escapeHtml(exp.id)}">移除</button></div></div>`).join(''):'<div class="empty"><strong>经历库还是空的</strong><p>课程项目、实习、社团、研究或个人作品都可以加入。一个经历可以关联多个岗位要求。</p></div>';
    const materialPanel=`<section class="section material-section"><div class="section-head"><div><h2>原始材料与待核对草稿</h2><p>可先保留旧简历、项目说明等原文；原文不会自动变成已确认经历。</p></div><button class="button small" data-act="add-material">+ 粘贴材料</button></div>${state.materials.length?`<div class="card">${state.materials.map(item=>`<div class="job-row"><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.type)} · ${escapeHtml(item.date)}</p><details><summary>查看原文</summary><p class="material-raw">${escapeHtml(item.raw)}</p></details></div><div class="row"><button class="button small" data-act="from-material" data-id="${escapeHtml(item.id)}">建立经历草稿</button><button class="button ghost small danger" data-act="remove-material" data-id="${escapeHtml(item.id)}">移除材料</button></div></div>`).join('')}</div>`:'<div class="empty"><strong>还没有个人材料</strong><p>可以跳过，直接逐项填写经历；也可以先粘贴原文，再建立并核对草稿。</p></div>'}</section>`;
    const reqCards=reqs.map(row=>{
      const answer=state.answers[row.key]||{status:'',experienceId:'',note:''};const [rank,tone]=priority(row);const exp=experienceById(answer.experienceId);const selectedExp=state.experiences.filter(item=>item.confirmed||item.id===answer.experienceId);
      return `<article class="card req-card" data-requirement="${escapeHtml(row.key)}"><div class="card-header"><div><h3>${escapeHtml(row.label)}</h3><p class="muted">${row.count}/${savedJobs().length} 条岗位提及 · ${row.sources.map(s=>escapeHtml(s.company)).join('、')}</p></div><span class="tag ${tone}">${rank}</span></div><p>你是否有能够说明这一要求的真实经历？</p><div class="choice-row"><button class="choice ${answer.status==='has'?'selected':''}" data-act="answer-status" data-key="${escapeHtml(row.key)}" data-status="has" aria-pressed="${answer.status==='has'}">有相关经历</button><button class="choice ${answer.status==='none'?'selected':''}" data-act="answer-status" data-key="${escapeHtml(row.key)}" data-status="none" aria-pressed="${answer.status==='none'}">目前没有</button><button class="choice ${answer.status==='unsure'?'selected':''}" data-act="answer-status" data-key="${escapeHtml(row.key)}" data-status="unsure" aria-pressed="${answer.status==='unsure'}">暂不确定</button></div>${answer.status==='has'?`<div class="answer-detail"><label class="field"><span>关联一段已核对的经历 *</span><select data-answer-experience="${escapeHtml(row.key)}"><option value="">请选择经历</option>${selectedExp.map(item=>`<option value="${escapeHtml(item.id)}" ${item.id===answer.experienceId?'selected':''}>${escapeHtml(item.title)}${item.confirmed?'':'（待核对）'}</option>`).join('')}</select></label><button class="button ghost small" data-act="add-experience">+ 新增经历</button><label class="field" style="margin-top:10px"><span>这段经历如何对应要求（可选）</span><textarea data-answer-note="${escapeHtml(row.key)}" placeholder="如：我在项目中负责了哪部分，使用了什么方法，留下什么成果……">${escapeHtml(answer.note)}</textarea></label>${exp&&!exp.confirmed?'<p class="caption">关联的经历尚未核对，确认前不能用于生成个人化计划。</p>':''}</div>`:''}${answer.status==='none'?'<div class="answer-detail muted">已记录“目前没有”。计划可建议积累实践，但不会把它写成能力不足。</div>':''}${answer.status==='unsure'?'<div class="answer-detail muted">已记录“暂不确定”。计划可先安排核实，而不是假设你没有经历。</div>':''}</article>`;
    }).join('');
    return head(2,'逐项核对经历，建立可复用的经历库','根据已收藏岗位的要求作答。你可以先管理经历，再把同一经历关联到多个要求；系统不会预设你的背景。',`<div class="actions"><button class="button" data-act="add-experience">+ 新增经历</button></div>`)+
      (!reqs.length?'<div class="notice warn"><strong>需要先收藏岗位</strong><p>具体岗位决定要核对哪些要求。你仍可以先在右侧建立经历库。</p></div>':`<div class="notice ${state.evidenceConfirmed?'good':''}"><strong>${state.evidenceConfirmed?'本轮核对已确认':`已完成 ${answered} / ${reqs.length} 项核对`}</strong><p>选择“有相关经历”时需关联本人核对过的经历；选择“目前没有”或“暂不确定”可直接记录。</p></div>`)+materialPanel+
      `<div class="grid evidence-layout"><div>${reqs.length?reqCards:'<div class="empty"><strong>还没有岗位要求</strong><p>先到目标与岗位页收藏岗位。</p><div class="actions"><button class="button" data-page="goal">去收藏岗位</button></div></div>'}${reqs.length?'<div class="actions"><button class="button primary" data-act="confirm-evidence">确认本轮核对并查看计划 →</button></div>':''}</div><aside><div class="card"><div class="card-header"><div><h2>我的经历库</h2><p class="caption">新增、核对、修改与关联</p></div><button class="button small" data-act="add-experience">新增</button></div>${experienceList}</div></aside></div>`;
  }
  function answerComplete(key){const answer=state.answers[key];if(!answer?.status)return false;if(answer.status==='has'){const exp=experienceById(answer.experienceId);return !!exp?.confirmed}return true}
  function suggestedPlans(){
    const rows=requirements();const suggestions=[];
    for(const row of rows){const answer=state.answers[row.key];if(!answer)continue;
      let title,reason,output,criteria,steps,estimate;
      if(answer.status==='none'){
        title=`为「${row.label}」完成一个小实践`;reason=`${row.count} 条岗位提到该要求；你目前没有对应经历。建议先产出可展示的实践成果。`;output='一份小项目记录或作品';criteria='能说明问题、行动、结果与局限';steps=['选择一个可完成的小问题','完成一次真实实践并记录过程','整理成果、个人贡献和局限'];estimate=4;
      }else if(answer.status==='unsure'){
        title=`核实「${row.label}」相关经历`;reason=`你对这一要求是否有相关经历暂不确定，先核实事实再决定是否补充实践。`;output='一条已核对的经历记录';criteria='确认有无对应经历，并说明依据';steps=['回顾课程、项目和其他实践','找到可说明该要求的具体行动','更新经历库并重新核对'];estimate=1.5;
      }else{
        const exp=experienceById(answer.experienceId);title=`整理「${row.label}」经历案例`;reason=`你已关联“${exp?.title||'相关经历'}”，可先把个人行动和成果表达清楚。`;output='一页经历案例草稿';criteria='讲清个人职责、方法、成果和局限';steps=['梳理经历背景和目标','写清个人行动与使用的方法','补充成果证据和可改进之处'];estimate=2.5;
      }
      suggestions.push({id:`suggest-${row.key}`,requirementKey:row.key,title,reason,output,criteria,hours:estimate,week:'本周',steps:steps.map((text,index)=>({id:`s-${index}`,text,done:false})),status:'suggested',origin:'智能体建议'});
    }
    const latestFeedback=state.feedback.at(-1);
    if(latestFeedback){
      const relatedJob=jobById(latestFeedback.jobId);
      suggestions.splice(3);
      suggestions.push({id:`feedback-${latestFeedback.id}`,requirementKey:'',title:'根据最近的求职反馈做一次针对性复盘',reason:`你记录了${relatedJob?`“${relatedJob.title}”的`:''}${latestFeedback.type}：${latestFeedback.note}。先确认事实和可调整之处，再决定下一步。`,output:'一页反馈复盘与下一步行动',criteria:'区分已知事实与推测，写出一项可执行的改进',hours:1.5,week:'本周',steps:[{id:'f-0',text:'整理反馈中确定发生的事实',done:false},{id:'f-1',text:'找出与岗位要求或经历表达相关的可调整点',done:false},{id:'f-2',text:'记录一次练习或材料修改的结果',done:false}],status:'suggested',origin:'求职反馈'});
    }
    return suggestions.slice(0,4);
  }
  function ensureSuggestions(){if(!state.evidenceConfirmed)return;const generated=suggestedPlans();let changed=false;for(const item of generated){if(!state.plans.some(plan=>plan.id===item.id)){state.plans.push(item);changed=true}}if(changed)save()}
  function renderPlans(){ensureSuggestions();const adopted=state.plans.filter(p=>p.status==='adopted');const adoptedHours=adopted.reduce((n,p)=>n+Number(p.hours||0),0);const budget=Number(state.goal.hours||6);const ready=state.evidenceConfirmed&&requirements().length>0;
    const planCards=state.plans.filter(p=>p.status!=='dismissed').map(plan=>`<article class="card plan-card"><div class="card-header"><div><div class="row" style="margin-bottom:6px"><span class="tag ${plan.status==='adopted'?'green':plan.status==='completed'?'blue':''}">${plan.status==='adopted'?'已采纳':plan.status==='completed'?'已完成':'建议草稿'}</span><span class="tag">${escapeHtml(plan.origin||'自定义')}</span></div><h3>${escapeHtml(plan.title)}</h3></div><span class="tag ${plan.status==='adopted'?'green':''}">${escapeHtml(plan.week)}</span></div><p class="reason">${escapeHtml(plan.reason)}</p><div class="plan-meta"><span class="tag">约 ${hours(plan.hours)}</span><span class="tag">产出：${escapeHtml(plan.output)}</span></div><ol class="steps">${plan.steps.map(step=>`<li>${escapeHtml(step.text)}</li>`).join('')}</ol><div class="caption">完成标准：${escapeHtml(plan.criteria)}</div><div class="actions"><button class="button small" data-act="edit-plan" data-id="${escapeHtml(plan.id)}">修改部分内容</button>${plan.status==='suggested'?`<button class="button primary small" data-act="adopt-plan" data-id="${escapeHtml(plan.id)}">采纳</button><button class="button ghost small" data-act="dismiss-plan" data-id="${escapeHtml(plan.id)}">不采纳</button>`:''}${plan.status==='adopted'?`<button class="button small" data-act="unadopt-plan" data-id="${escapeHtml(plan.id)}">移回建议</button>`:''}</div></article>`).join('');
    return head(3,'从多个建议里，组合自己的准备计划','建议依据岗位要求与本人核对的经历。你可以采纳多项、只改某些步骤或时间，也可以不采纳。',`<div class="actions"><button class="button" data-act="add-plan">+ 自定义任务</button></div>`)+
      (!ready?'<div class="notice warn"><strong>先完成岗位要求与经历的核对</strong><p>计划会用到你本人确认的状态。现在仍可创建自定义任务，但不会生成个人化建议。</p><div class="actions"><button class="button" data-page="evidence">去核对经历</button></div></div>':`<div class="notice good"><strong>已依据 ${requirements().length} 项岗位要求生成建议</strong><p>建议保留原因与来源；采纳后才会出现在“执行计划”页面。修改建议不会覆盖你已保存的经历。</p></div>`)+
      `<div class="card"><div class="between"><div><h2>本周投入安排</h2><p class="caption">已采纳 ${adopted.length} 项 · 预计 ${hours(adoptedHours)} / 可用 ${hours(budget)}</p></div><span class="tag ${adoptedHours>budget?'amber':'green'}">${adoptedHours>budget?'超过可用时间':'可调整节奏'}</span></div><div class="budget"><div class="meter ${adoptedHours>budget?'over':''}"><span style="width:${Math.min(100,budget?adoptedHours/budget*100:0)}%"></span></div></div>${adoptedHours>budget?'<p class="caption" style="color:var(--amber)">可把部分任务移到下周，或减少步骤；计划仍由你决定。</p>':''}</div>`+
      `<section class="section"><div class="section-head"><div><h2>计划建议与已采纳任务</h2><p>每张卡片都包含理由、预计用时、行动、产出和完成标准。</p></div>${ready?'<button class="button small" data-act="refresh-plans">按当前核对结果补充建议</button>':''}</div>${planCards?`<div class="grid three">${planCards}</div>`:'<div class="empty"><strong>还没有计划</strong><p>完成经历核对后会出现建议；也可以先创建自己的任务。</p></div>'}</section>`+
      (state.plans.some(p=>p.status==='dismissed')?`<section class="section"><div class="section-head"><h2>未采纳的建议</h2></div><div class="card">${state.plans.filter(p=>p.status==='dismissed').map(p=>`<div class="job-row"><span>${escapeHtml(p.title)}</span><button class="button small" data-act="restore-plan" data-id="${escapeHtml(p.id)}">重新考虑</button></div>`).join('')}</div></section>`:'')+
      `<div class="actions"><button class="button primary" data-page="today">进入执行计划 →</button></div>`;
  }
  function renderToday(){const active=state.plans.filter(p=>p.status==='adopted');const next=active[0];const completed=state.plans.filter(p=>p.status==='completed').length;
    const cards=active.map(plan=>{const done=plan.steps.filter(s=>s.done).length;return `<article class="card"><div class="card-header"><div><h2>${escapeHtml(plan.title)}</h2><p class="caption">${escapeHtml(plan.week)} · 约 ${hours(plan.hours)} · ${done}/${plan.steps.length} 步完成</p></div><span class="tag green">进行中</span></div><div class="divider"></div>${plan.steps.map(step=>`<div class="today-task ${step.done?'done':''}"><input type="checkbox" id="step-${escapeHtml(plan.id)}-${escapeHtml(step.id)}" data-task-plan="${escapeHtml(plan.id)}" data-task-step="${escapeHtml(step.id)}" ${step.done?'checked':''}><label for="step-${escapeHtml(plan.id)}-${escapeHtml(step.id)}">${escapeHtml(step.text)}</label></div>`).join('')}<div class="actions"><button class="button primary" data-act="submit-outcome" data-id="${escapeHtml(plan.id)}" ${done<plan.steps.length?'disabled':''}>保存成果并完成任务</button><button class="button" data-act="edit-plan" data-id="${escapeHtml(plan.id)}">调整任务</button></div>${done<plan.steps.length?'<div class="caption">完成当前计划的步骤后，可提交成果；勾选进度会自动保存。</div>':''}</article>`}).join('');
    return head(4,'执行计划，按自己的节奏推进','这里集中呈现已采纳的任务。逐步完成行动并记录成果；计划可调整，进度会保留。')+
      `<div class="grid three"><div class="card"><h2>当前目标</h2><p style="margin-top:9px">${state.goal.title?escapeHtml(state.goal.title):'尚未设定'}</p><div class="caption">${escapeHtml(state.goal.city||'城市未设置')}</div></div><div class="card"><h2>进行中的任务</h2><p style="margin-top:9px;font-size:22px;color:var(--ink)">${active.length}</p><div class="caption">下一步：${next?escapeHtml(next.steps.find(s=>!s.done)?.text||'保存成果'): '先采纳一项计划'}</div></div><div class="card"><h2>已留存成果</h2><p style="margin-top:9px;font-size:22px;color:var(--ink)">${state.outcomes.length}</p><div class="caption">${completed} 项任务已完成</div></div></div>`+
      `<section class="section"><div class="section-head"><div><h2>正在执行的任务</h2><p>勾选行动后可记录成果；完成状态与成果分别保存。</p></div></div>${active.length?`<div class="grid">${cards}</div>`:'<div class="empty"><strong>还没有执行中的任务</strong><p>去准备计划页选择任务；如果暂时没有时间，也可以先浏览岗位要求。</p><div class="actions"><button class="button primary" data-page="plans">查看准备计划</button></div></div>'}</section>`;
  }
  function renderReview(){const outcomeRows=state.outcomes.map(item=>{const plan=state.plans.find(p=>p.id===item.planId);return `<div class="outcome-card"><div class="between"><strong>${escapeHtml(plan?.title||'准备成果')}</strong><span class="tag green">已保存</span></div><p>${escapeHtml(item.description)}</p>${item.link?`<a href="${escapeHtml(safeUrl(item.link))}" target="_blank" rel="noopener noreferrer" class="caption">查看成果链接 ↗</a>`:''}<div class="caption">${escapeHtml(item.date)}</div></div>`}).join('');
    const feedbackRows=state.feedback.map(item=>{const job=jobById(item.jobId);return `<div class="outcome-card"><div class="between"><strong>${escapeHtml(job?.title||'岗位反馈')}</strong><span class="tag">${escapeHtml(item.type)}</span></div><p>${escapeHtml(item.note)}</p><div class="caption">${escapeHtml(item.date)}</div></div>`}).join('');
    const applicationRows=[...savedJobs(),...archivedJobs()].map(job=>{const record=latestApplication(job.id);return `<div class="job-row"><div><strong>${escapeHtml(job.title)}</strong><p>${escapeHtml(job.company)}${record?' · '+escapeHtml(record.date):' · 尚无投递记录'}${state.archivedJobIds.includes(job.id)?' · 已归档':''}</p>${record?.note?`<p>${escapeHtml(record.note)}</p>`:''}</div><span class="tag ${state.jobStatus[job.id]==='interview'?'green':''}">${statusLabel(state.jobStatus[job.id])}</span></div>`}).join('');
    return head(5,'保留成果，用真实反馈调整下一轮','完成任务后保存作品或经历；投递与面试状态由你更新，AI 只用已确认信息提出下一版建议。',`<div class="actions"><button class="button" data-act="add-feedback">+ 记录反馈</button></div>`)+
      `<div class="grid"><section class="card"><div class="card-header"><h2>我的成果</h2><span class="tag">${state.outcomes.length} 份</span></div>${outcomeRows||'<div class="empty"><strong>还没有保存成果</strong><p>完成准备任务后，可以保存描述与作品链接。</p></div>'}</section><section class="card"><div class="card-header"><h2>岗位与申请进度</h2><span class="tag">${savedJobs().length} 条</span></div>${applicationRows||'<div class="empty"><strong>还没有岗位</strong><p>先收藏岗位，再由你记录实际投递状态。</p></div>'}<div class="actions"><button class="button small" data-page="goal">管理岗位</button></div></section></div>`+
      `<section class="section"><div class="section-head"><div><h2>真实反馈</h2><p>例如面试中被追问的项目细节，或你观察到的岗位变化。</p></div><button class="button small" data-act="add-feedback">记录一条</button></div><div class="card">${feedbackRows||'<div class="empty"><strong>还没有反馈记录</strong><p>没有反馈时，系统不会编造原因或替你判断申请结果。</p></div>'}</div></section>`+
      `<section class="section"><div class="notice"><strong>开始下一轮准备</strong><p>如果目标岗位、经历或求职反馈变化，可重新核对岗位要求，并生成新的建议草稿。已采纳任务和成果不会被自动覆盖。</p><div class="actions"><button class="button" data-page="evidence">重新核对经历</button><button class="button primary" data-act="refresh-plans">生成新建议并查看计划 →</button></div></div></section>`;
  }
  function safeUrl(raw){try{const url=new URL(raw);return ['http:','https:'].includes(url.protocol)?url.href:'#'}catch{return '#'}}
  function assessmentHtml(job){
    const issues=[];
    if(state.goal.city&&job.city&&state.goal.city!==job.city)issues.push(`求职城市为“${state.goal.city}”，岗位在“${job.city}”`);
    const available=String(state.goal.days||'').match(/每周\s*(\d+(?:\.\d+)?)\s*天/),required=job.schedule?.match(/每周\s*(\d+(?:\.\d+)?)\s*天/);
    if(available&&required&&Number(available[1])<Number(required[1]))issues.push(`你填写每周可到岗 ${available[1]} 天，岗位要求 ${required[1]} 天`);
    const evidence=job.requirements.map(req=>{const answer=state.answers[req.key];const exp=experienceById(answer?.experienceId);const label=answer?.status==='has'&&exp?.confirmed?'已有核对经历':answer?.status==='none'?'目前没有':answer?.status==='unsure'?'待核实':'尚未核对';return `<span class="tag ${label==='已有核对经历'?'green':label==='目前没有'?'amber':''}">${escapeHtml(req.label)} · ${label}</span>`}).join('');
    return `<div class="job-assessment"><strong>条件与经历对照</strong><p class="caption">只对明确填写的信息提示冲突；没有资料时不推断你是否胜任。</p>${issues.length?`<div class="notice warn"><strong>需要先核对的条件</strong><p>${issues.map(escapeHtml).join('；')}</p></div>`:'<p class="caption">目前没有从已填写信息中发现明确条件冲突；到岗时间和其他限制仍需你核对。</p>'}<div class="row" style="margin-top:9px">${evidence}</div><div class="actions"><button type="button" class="button small" data-page="evidence">补充或核对经历</button></div></div>`;
  }
  function showModal(title,body,submitLabel='保存',formId='modal-form'){$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><h2 id="modal-title">${title}</h2><button class="close" data-act="close-modal" aria-label="关闭">×</button></header><form id="${formId}">${body}<div class="actions"><button class="button" type="button" data-act="close-modal">取消</button><button class="button primary" type="submit">${submitLabel}</button></div></form></div></div>`;$('.modal input,.modal textarea,.modal select')?.focus()}
  function closeModal(){$('#modal-root').innerHTML=''}
  function openJobModal(id=''){const job=state.customJobs.find(item=>item.id===id);showModal(job?'编辑文件夹中的岗位':'手动添加岗位',`<input type="hidden" name="id" value="${escapeHtml(job?.id||'')}"><label class="field"><span>岗位名称 *</span><input name="title" required placeholder="如：产品经理实习生" value="${escapeHtml(job?.title||'')}"></label><div class="field-row"><label class="field"><span>公司或来源 *</span><input name="company" required placeholder="公司名称" value="${escapeHtml(job?.company||'')}"></label><label class="field"><span>城市</span><input name="city" placeholder="如：上海" value="${escapeHtml(job?.city||'')}"></label></div><div class="field-row"><label class="field"><span>岗位链接（可选）</span><input name="sourceUrl" type="url" placeholder="https://..." value="${escapeHtml(job?.sourceUrl||'')}"></label><label class="field"><span>记录日期</span><input name="capturedAt" type="date" value="${escapeHtml(job?.capturedAt||new Date().toLocaleDateString('en-CA'))}"></label></div><label class="field"><span>JD 原文（可选，保留来源快照）</span><textarea name="rawJD" placeholder="粘贴岗位描述原文；链接无法读取时也可以继续手动添加。">${escapeHtml(job?.rawJD||'')}</textarea></label><label class="field"><span>用于汇总的岗位要求（每行一项） *</span><textarea name="requirements" required placeholder="例如：参与用户需求调研\n能够输出产品方案\n熟悉基础数据分析">${escapeHtml(job?.requirements.map(item=>item.quote).join('\n')||'')}</textarea></label><p class="caption">原型不会抓取招聘平台。请自行核对并粘贴 JD；更新后原版本会留存，相关经历需要重新确认。</p>`,'保存岗位','custom-job-form')}
  function openJobDetail(id){const job=jobById(id);if(!job)return;const snapshots=state.jobSnapshots[id]||[];const history=snapshots.length?`<details class="raw-jd"><summary>查看 ${snapshots.length} 个旧版岗位快照</summary>${snapshots.map((item,index)=>`<div class="outcome-card"><strong>旧版 ${index+1} · ${escapeHtml(item.date)}</strong><p>${escapeHtml(item.job.company)} · ${escapeHtml(item.job.title)}</p><p class="material-raw">${escapeHtml(item.job.rawJD||item.job.requirements.map(row=>row.quote).join('\n'))}</p></div>`).join('')}</details>`:'';showModal(escapeHtml(job.title),`<p class="caption">${escapeHtml(job.company)} · ${escapeHtml(job.city||'城市未设置')} · ${escapeHtml(job.schedule||'到岗安排待确认')}</p><p class="caption">来源：${job.sourceUrl?`<a href="${escapeHtml(safeUrl(job.sourceUrl))}" target="_blank" rel="noopener noreferrer">打开原岗位 ↗</a>`:'用户手动提供或演示岗位'}${job.capturedAt?' · 记录于 '+escapeHtml(job.capturedAt):''}</p>${assessmentHtml(job)}<div class="divider"></div><h3>岗位要求与原文依据</h3>${job.requirements.map(req=>`<div class="outcome-card"><strong>${escapeHtml(req.label)}</strong><p>「${escapeHtml(req.quote)}」</p><span class="tag ${req.must?'amber':''}">${req.must?'岗位写明必备':'岗位提及'}</span></div>`).join('')}${job.rawJD?`<details class="raw-jd"><summary>查看保存的 JD 原文</summary><p>${escapeHtml(job.rawJD)}</p></details>`:''}${history}<p class="caption">岗位原文和已核对经历分别保留；修改岗位后需重新确认受影响的要求。</p>`,'关闭','detail-form')}
  function suggestedDraft(job){const exp=state.experiences.find(item=>item.confirmed);const evidence=exp?`我整理了一段已核对的经历：“${exp.title}”。\n${exp.description.trim()}`:'我正在整理与该岗位相关的经历，以下内容需要由我补充真实项目事实。';return `你好，我关注到 ${job.company} 的「${job.title}」岗位。\n\n${evidence}\n\n我希望进一步了解岗位的具体工作内容与申请方式。感谢阅读。`;}
  function openDraftModal(id){const job=jobById(id);if(!job)return;if(!state.shortlistJobIds.includes(id)){toast('请先将岗位标记为优先推进');return}const versions=state.jobDrafts[id]||[];showModal('沟通草稿 · '+escapeHtml(job.title),`<input type="hidden" name="jobId" value="${escapeHtml(id)}"><p class="caption">只引用岗位信息和本人已确认的经历。草稿由你检查、编辑和决定是否使用。</p><label class="field"><span>可编辑草稿 *</span><textarea name="body" required style="min-height:190px">${escapeHtml(versions.at(-1)?.body||suggestedDraft(job))}</textarea></label><p class="caption">保存只会留在本站；复制文字或到原平台发送仍由你操作。</p>${versions.length?`<details><summary>查看 ${versions.length} 个已保存版本</summary>${versions.map((version,index)=>`<div class="outcome-card"><strong>第 ${index+1} 版 · ${escapeHtml(version.date)}</strong><p style="white-space:pre-wrap">${escapeHtml(version.body)}</p></div>`).join('')}</details>`:''}`,'保存这一版','draft-form');}
  function openApplicationModal(id){const job=jobById(id);if(!job)return;if(!state.shortlistJobIds.includes(id)&&!latestApplication(id)){toast('请先将岗位标记为优先推进');return}const recent=latestApplication(id);showModal('记录投递与后续状态 · '+escapeHtml(job.title),`<input type="hidden" name="jobId" value="${escapeHtml(id)}"><p class="caption">请在原招聘平台完成真实操作；这里仅记录你确认的结果。${job.sourceUrl?` <a href="${escapeHtml(safeUrl(job.sourceUrl))}" target="_blank" rel="noopener noreferrer">打开岗位来源 ↗</a>`:''}</p><div class="field-row"><label class="field"><span>当前实际状态 *</span><select name="status"><option value="saved" ${(state.jobStatus[id]||'saved')==='saved'?'selected':''}>未投递</option><option value="waiting" ${['waiting','applied'].includes(state.jobStatus[id])?'selected':''}>已投递，等待反馈</option><option value="interview" ${state.jobStatus[id]==='interview'?'selected':''}>已确认面试安排</option><option value="closed" ${state.jobStatus[id]==='closed'?'selected':''}>已结束</option></select></label><label class="field"><span>实际日期 *</span><input name="date" type="date" required value="${escapeHtml(recent?.date||new Date().toLocaleDateString('en-CA'))}"></label></div><label class="field"><span>备注或后续安排</span><textarea name="note" placeholder="例如：已在官网提交，尚无消息；或收到面试安排的时间。">${escapeHtml(recent?.note||'')}</textarea></label><label class="row"><input type="checkbox" name="confirmed" required> 我确认填写的是实际状态；如涉及投递或面试，已在原平台核实</label><p class="caption">“已投递且暂无消息”记为“等待反馈”；没有收到确认，不会自动记为面试中。</p>`,'保存记录','application-form');}
  function openMaterialModal(){showModal('保留原始个人材料',`<label class="field"><span>材料名称 *</span><input name="title" required placeholder="如：旧版简历、课程项目说明"></label><label class="field"><span>材料类型</span><select name="type"><option>简历</option><option>项目说明</option><option>作品说明</option><option>其他</option></select></label><label class="field"><span>粘贴原文 *</span><textarea name="raw" required style="min-height:170px" placeholder="粘贴你愿意在原型中整理的文字；保存后不会自动成为已确认经历。"></textarea></label><p class="caption">原文会保留。你需要从材料建立草稿，并逐项核对后才能用于个人化建议。</p>`,'保存材料','material-form')}
  function openExperienceFromMaterial(id){const material=state.materials.find(item=>item.id===id);if(!material)return;showModal('从材料建立经历草稿',`<input type="hidden" name="materialId" value="${escapeHtml(id)}"><label class="field"><span>经历名称 *</span><input name="title" required value="${escapeHtml(material.title)}"></label><label class="field"><span>经历类型</span><select name="type"><option>课程项目</option><option>实习</option><option>研究</option><option>社团</option><option>个人作品</option><option>其他</option></select></label><label class="field"><span>时间</span><input name="period" placeholder="如：2026 春季"></label><label class="field"><span>请核对并改写个人真实行动 *</span><textarea name="description" required style="min-height:160px">${escapeHtml(material.raw)}</textarea></label><label class="field"><span>作品或证明链接（可选）</span><input name="link" type="url"></label><label class="row"><input type="checkbox" name="confirmed"> 我已核对上面的事实</label><p class="caption">这是材料草稿，不会因粘贴原文就自动认定为你的能力或成果。</p>`,'保存经历草稿','experience-form')}
  function openExperienceModal(id=''){const exp=experienceById(id);showModal(exp?'编辑经历':'新增经历',`<input type="hidden" name="id" value="${escapeHtml(exp?.id||'')}"><label class="field"><span>经历名称 *</span><input name="title" required placeholder="如：课程产品设计项目" value="${escapeHtml(exp?.title||'')}"></label><div class="field-row"><label class="field"><span>经历类型</span><select name="type">${['课程项目','实习','研究','社团','个人作品','其他'].map(type=>`<option ${exp?.type===type?'selected':''}>${type}</option>`).join('')}</select></label><label class="field"><span>时间</span><input name="period" placeholder="如：2026 春季" value="${escapeHtml(exp?.period||'')}"></label></div><label class="field"><span>真实做过的事 *</span><textarea name="description" required placeholder="写清你个人负责了什么、做了什么；没有结果数据可以留空。">${escapeHtml(exp?.description||'')}</textarea></label><label class="field"><span>作品或证明链接（可选）</span><input name="link" type="url" placeholder="https://..." value="${escapeHtml(exp?.link||'')}"></label><label class="row"><input type="checkbox" name="confirmed" ${exp?.confirmed?'checked':''}> 我已核对上面的事实</label><p class="caption">同一段经历可以关联多个岗位要求，修改后相关分析会提示重新确认。</p>`,'保存经历','experience-form')}
  function openPlanModal(id=''){const plan=state.plans.find(p=>p.id===id);showModal(plan?'部分修改计划':'新增自定义任务',`<input type="hidden" name="id" value="${escapeHtml(plan?.id||'')}"><label class="field"><span>任务名称 *</span><input name="title" required value="${escapeHtml(plan?.title||'')}"></label><div class="field-row"><label class="field"><span>预计投入（小时）</span><input type="number" name="hours" min="0.5" max="40" step="0.5" value="${escapeHtml(plan?.hours||2)}"></label><label class="field"><span>安排时间</span><select name="week">${['本周','下周','暂不安排'].map(week=>`<option ${plan?.week===week?'selected':''}>${week}</option>`).join('')}</select></label></div><label class="field"><span>预期产出 *</span><input name="output" required value="${escapeHtml(plan?.output||'')}"></label><label class="field"><span>完成标准</span><input name="criteria" value="${escapeHtml(plan?.criteria||'')}"></label><label class="field"><span>建议理由或自己的说明</span><textarea name="reason">${escapeHtml(plan?.reason||'由我自行设定的准备任务。')}</textarea></label><div class="field"><span>选择并修改要保留的行动</span>${(plan?.steps||[{id:'new-1',text:'明确行动和预期产出',done:false}]).map(step=>`<div class="step-edit"><input type="checkbox" name="keep-step" value="${escapeHtml(step.id)}" checked aria-label="保留这一步"><input class="inline-input" name="step-text-${escapeHtml(step.id)}" type="text" value="${escapeHtml(step.text)}" aria-label="行动内容"></div>`).join('')}<textarea name="new-steps" placeholder="增加行动：每行一项" style="min-height:65px;margin-top:7px"></textarea><div class="caption">取消勾选可移除步骤；改文字只影响这一项计划。</div></div>`,'保存修改','plan-form')}
  function openOutcomeModal(id){const plan=state.plans.find(p=>p.id===id);if(!plan)return;showModal('保存任务成果',`<input name="planId" type="hidden" value="${escapeHtml(id)}"><p class="caption">${escapeHtml(plan.title)}</p><label class="field"><span>实际完成了什么 *</span><textarea name="description" required placeholder="写下真实行动、结果与尚未解决的问题。"></textarea></label><label class="field"><span>成果链接（可选）</span><input name="link" type="url" placeholder="https://..."></label><p class="caption">保存成果会将任务标为已完成，但不代表能力自动获得认证。</p>`,'保存成果','outcome-form')}
  function openFeedbackModal(){showModal('记录真实反馈',`<label class="field"><span>相关岗位</span><select name="jobId"><option value="">暂不关联岗位</option>${savedJobs().map(job=>`<option value="${escapeHtml(job.id)}">${escapeHtml(job.company)} · ${escapeHtml(job.title)}</option>`).join('')}</select></label><label class="field"><span>反馈类型</span><select name="type"><option>投递进展</option><option>面试反馈</option><option>岗位变化</option><option>其他观察</option></select></label><label class="field"><span>实际发生了什么 *</span><textarea name="note" required placeholder="只记录你确认的事实，推测可以明确标注为推测。"></textarea></label>`,'保存反馈','feedback-form')}
  function refreshPlans(){if(!state.evidenceConfirmed){toast('请先完成经历核对，再生成建议');navigate('evidence');return}for(const item of suggestedPlans()){const existing=state.plans.find(p=>p.id===item.id);if(!existing)state.plans.push(item);else if(existing.status==='dismissed')existing.status='suggested'}save();navigate('plans');toast('已根据当前核对结果整理建议；已采纳任务保持不变')}
  function reset(){if(!confirm('清空此浏览器中的原型数据并重新开始？'))return;state=initialState();save();navigate('goal');toast('已重置体验')}
  document.addEventListener('click',event=>{
    const target=event.target.closest('[data-page],[data-act]');if(!target)return;
    if(target.dataset.page){navigate(target.dataset.page);return}
    const {act,id}=target.dataset;
    if(act==='reset'){reset();return}if(act==='close-modal'){closeModal();return}
    if(act==='toggle-job'){if(state.savedJobIds.includes(id)){state.savedJobIds=state.savedJobIds.filter(x=>x!==id);state.shortlistJobIds=state.shortlistJobIds.filter(x=>x!==id);if(state.applicationRecords.some(record=>record.jobId===id)&&!state.archivedJobIds.includes(id))state.archivedJobIds.push(id)}else{state.archivedJobIds=state.archivedJobIds.filter(x=>x!==id);state.savedJobIds.push(id);state.jobStatus[id] ||= 'saved'}state.evidenceConfirmed=false;save();render();return}
    if(act==='shortlist-job'){state.shortlistJobIds=state.shortlistJobIds.includes(id)?state.shortlistJobIds.filter(x=>x!==id):[...state.shortlistJobIds,id];save();render();return}
    if(act==='archive-job'){state.savedJobIds=state.savedJobIds.filter(x=>x!==id);state.shortlistJobIds=state.shortlistJobIds.filter(x=>x!==id);if(!state.archivedJobIds.includes(id))state.archivedJobIds.push(id);state.evidenceConfirmed=false;save();render();toast('已归档，投递和草稿历史仍保留');return}
    if(act==='restore-job'){state.archivedJobIds=state.archivedJobIds.filter(x=>x!==id);if(!state.savedJobIds.includes(id))state.savedJobIds.push(id);state.evidenceConfirmed=false;save();render();toast('已恢复到目标文件夹');return}
    if(act==='view-job'){openJobDetail(id);return}if(act==='open-custom-job'){openJobModal();return}if(act==='edit-job'){openJobModal(id);return}
    if(act==='draft-job'){openDraftModal(id);return}if(act==='application-job'){openApplicationModal(id);return}
    if(act==='add-material'){openMaterialModal();return}if(act==='from-material'){openExperienceFromMaterial(id);return}
    if(act==='remove-material'){if(!confirm('移除这份原始材料？已建立的经历草稿会保留。'))return;state.materials=state.materials.filter(item=>item.id!==id);save();render();return}
    if(act==='add-experience'){openExperienceModal();return}if(act==='edit-experience'){openExperienceModal(id);return}
    if(act==='remove-experience'){if(!confirm('移除这段经历？已关联的要求将需要重新核对。'))return;state.experiences=state.experiences.filter(x=>x.id!==id);for(const answer of Object.values(state.answers))if(answer.experienceId===id)answer.experienceId='';state.evidenceConfirmed=false;save();render();return}
    if(act==='answer-status'){state.answers[target.dataset.key] ||= {status:'',experienceId:'',note:''};state.answers[target.dataset.key].status=target.dataset.status;state.evidenceConfirmed=false;save();render();return}
    if(act==='confirm-evidence'){const incomplete=requirements().filter(req=>!answerComplete(req.key));if(incomplete.length){toast(`还有 ${incomplete.length} 项需要选择或关联已核对经历`);return}state.evidenceConfirmed=true;save();navigate('plans');toast('经历核对已确认');return}
    if(act==='refresh-plans'){refreshPlans();return}if(act==='add-plan'){openPlanModal();return}if(act==='edit-plan'){openPlanModal(id);return}
    if(act==='adopt-plan'||act==='dismiss-plan'||act==='restore-plan'||act==='unadopt-plan'){const plan=state.plans.find(p=>p.id===id);if(!plan)return;plan.status={ 'adopt-plan':'adopted','dismiss-plan':'dismissed','restore-plan':'suggested','unadopt-plan':'suggested'}[act];save();render();toast(plan.status==='adopted'?'已加入执行计划':'计划状态已更新');return}
    if(act==='submit-outcome'){openOutcomeModal(id);return}if(act==='add-feedback'){openFeedbackModal();return}
  });
  document.addEventListener('change',event=>{
    const target=event.target;
    if(target.dataset.jobStatus){state.jobStatus[target.dataset.jobStatus]=target.value;save();toast('投递状态已更新');return}
    if(target.dataset.answerExperience){state.answers[target.dataset.answerExperience] ||= {status:'has',experienceId:'',note:''};state.answers[target.dataset.answerExperience].experienceId=target.value;state.evidenceConfirmed=false;save();render();return}
    if(target.dataset.taskPlan){const plan=state.plans.find(p=>p.id===target.dataset.taskPlan);const step=plan?.steps.find(s=>s.id===target.dataset.taskStep);if(step){step.done=target.checked;save();render()}return}
  });
  document.addEventListener('input',event=>{if(event.target.dataset.answerNote){state.answers[event.target.dataset.answerNote] ||= {status:'has',experienceId:'',note:''};state.answers[event.target.dataset.answerNote].note=event.target.value;state.evidenceConfirmed=false;save()}});
  document.addEventListener('input',event=>{if(event.target.matches('[data-job-filter]')){const query=event.target.value.trim().toLowerCase();$$('.job-card').forEach(card=>{card.hidden=!card.textContent.toLowerCase().includes(query)})}});
  document.addEventListener('submit',event=>{
    const form=event.target;event.preventDefault();const values=new FormData(form);const name=form.getAttribute('id');
    if(name==='goal-form'){const title=String(values.get('title')||'').trim();if(!title)return;state.goal={title,city:String(values.get('city')||'').trim(),hours:Number(values.get('hours')||6),days:String(values.get('days')||'').trim()};state.evidenceConfirmed=false;save();render();toast('目标已保存');return}
    if(name==='material-form'){const title=String(values.get('title')||'').trim(),raw=String(values.get('raw')||'').trim();if(!title||!raw){toast('请填写材料名称和原文');return}state.materials.push({id:uid('material'),title,type:String(values.get('type')||'其他'),raw,date:new Date().toLocaleDateString('zh-CN')});save();closeModal();render();toast('原始材料已保留，接下来可建立待核对的经历草稿');return}
    if(name==='draft-form'){const jobId=String(values.get('jobId')||''),body=String(values.get('body')||'').trim();if(!jobById(jobId)||!body)return;state.jobDrafts[jobId] ||= [];state.jobDrafts[jobId].push({id:uid('draft'),body,date:new Date().toLocaleString('zh-CN')});save();closeModal();render();toast('草稿版本已保存；发送仍需本人在原平台操作');return}
    if(name==='application-form'){const jobId=String(values.get('jobId')||''),status=String(values.get('status')||'saved'),date=String(values.get('date')||''),note=String(values.get('note')||'').trim();if(!jobById(jobId)||!values.has('confirmed')||!date){toast('请确认实际状态与日期');return}state.jobStatus[jobId]=status;state.applicationRecords.push({id:uid('application'),jobId,status,date,note});save();closeModal();render();toast('本人确认的状态已保存，旧记录仍可查看');return}
    if(name==='custom-job-form'){const id=String(values.get('id')||'');const title=String(values.get('title')||'').trim();const company=String(values.get('company')||'').trim();const lines=String(values.get('requirements')||'').split('\n').map(x=>x.trim()).filter(Boolean);if(!title||!company||!lines.length){toast('请填写岗位、来源和至少一条要求');return}const city=String(values.get('city')||'').trim();const duplicate=allJobs().find(item=>item.id!==id&&item.title.trim().toLowerCase()===title.toLowerCase()&&item.company.trim().toLowerCase()===company.toLowerCase()&&String(item.city||'').trim().toLowerCase()===city.toLowerCase());if(duplicate){toast('同一公司、岗位和城市已存在，请编辑原岗位');return}const job={id:id||uid('job'),title,company,city:String(values.get('city')||'').trim(),schedule:'到岗安排待确认',sourceUrl:String(values.get('sourceUrl')||'').trim(),rawJD:String(values.get('rawJD')||'').trim(),capturedAt:String(values.get('capturedAt')||'').trim(),requirements:lines.map(line=>({key:`custom-${line.toLowerCase().replace(/\s+/g,'-')}`,label:line,quote:line,must:false}))};if(id){const previous=state.customJobs.find(item=>item.id===id);if(previous){state.jobSnapshots[id] ||= [];state.jobSnapshots[id].push({job:previous,date:new Date().toLocaleString('zh-CN')})}state.customJobs=state.customJobs.map(item=>item.id===id?job:item)}else{state.customJobs.push(job);state.savedJobIds.push(job.id);state.jobStatus[job.id]='saved'}state.evidenceConfirmed=false;save();closeModal();render();toast(id?'岗位已更新，旧版已保留':'岗位已加入目标文件夹');return}
    if(name==='experience-form'){const id=String(values.get('id')||'');const old=experienceById(id);const exp={id:id||uid('exp'),title:String(values.get('title')||'').trim(),type:String(values.get('type')||'课程项目'),period:String(values.get('period')||'').trim(),description:String(values.get('description')||'').trim(),link:String(values.get('link')||'').trim(),sourceMaterialId:String(values.get('materialId')||old?.sourceMaterialId||''),confirmed:values.get('confirmed')==='on'};if(!exp.title||!exp.description){toast('请填写经历名称和真实内容');return}if(id){state.experiences=state.experiences.map(x=>x.id===id?exp:x)}else state.experiences.push(exp);state.evidenceConfirmed=false;save();closeModal();render();toast(exp.confirmed?'已保存本人核对的经历':'经历草稿已保存');return}
    if(name==='plan-form'){const id=String(values.get('id')||'');const old=state.plans.find(p=>p.id===id);const existingSteps=old?.steps||[{id:'new-1',text:'明确行动和预期产出',done:false}];const kept=new Set(values.getAll('keep-step'));const steps=existingSteps.filter(s=>kept.has(s.id)).map(s=>({...s,text:String(values.get(`step-text-${s.id}`)||'').trim()})).filter(s=>s.text);const extra=String(values.get('new-steps')||'').split('\n').map(x=>x.trim()).filter(Boolean).map(text=>({id:uid('step'),text,done:false}));steps.push(...extra);if(!steps.length){toast('请至少保留一个行动步骤');return}const next={id:id||uid('plan'),requirementKey:old?.requirementKey||'',title:String(values.get('title')||'').trim(),reason:String(values.get('reason')||'').trim(),output:String(values.get('output')||'').trim(),criteria:String(values.get('criteria')||'').trim(),hours:Number(values.get('hours')||2),week:String(values.get('week')||'本周'),steps,status:old?.status||'suggested',origin:old?.origin||'自己添加'};if(!next.title||!next.output){toast('请填写名称和产出');return}if(id)state.plans=state.plans.map(p=>p.id===id?next:p);else state.plans.push(next);save();closeModal();render();toast('已保存对计划的修改');return}
    if(name==='outcome-form'){const planId=String(values.get('planId')||'');const plan=state.plans.find(p=>p.id===planId);if(!plan)return;const description=String(values.get('description')||'').trim();if(!description)return;state.outcomes.push({id:uid('outcome'),planId,description,link:String(values.get('link')||'').trim(),date:new Date().toLocaleDateString('zh-CN')});plan.status='completed';save();closeModal();navigate('review');toast('成果已保存，任务标记为已完成');return}
    if(name==='feedback-form'){const note=String(values.get('note')||'').trim();if(!note)return;state.feedback.push({id:uid('feedback'),jobId:String(values.get('jobId')||''),type:String(values.get('type')||'其他观察'),note,date:new Date().toLocaleDateString('zh-CN')});save();closeModal();render();toast('反馈已记录');return}
    if(name==='detail-form'){closeModal()}
  });
  document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal()});
  $('#mobile-menu').addEventListener('click',()=>document.body.classList.toggle('nav-open'));
  render();
})();
